  hero_statement_ja = '本契約の前にアドバイスすることが、最も役に立つ場合もあります。',
  overview_ja = ARRAY['すべての案件が、フル制作の施工から始まる必要はありません。会場の評価、予算感の把握、「ハイブリッド」に実際何が必要かの検討など、企画の初期段階にあるチーム向けに、契約前に技術面を整理するための単独コンサルティングを提供します。', '会場の技術評価、予算スコーピング、RFP・ベンダー選定資料の支援、そして他社ベンダーや社内チームが作成した技術プランのセカンドオピニオンレビューを含みます。']::text[],
  capabilities_ja = ARRAY['会場の技術評価・現地視察', '予算スコーピング・技術的実現可能性のレビュー', 'RFP・ベンダー選定資料への技術的助言', '既存の技術プランのセカンドオピニオンレビュー', '形式（対面・ハイブリッド・バーチャル）に関するガイダンス', '複数ベンダーが関わるイベントの調整アドバイス']::text[],
  process_ja = '[{"title":"ヒアリング","description":"イベント内容、制約条件、そして貴社が下そうとしている判断を理解します。"},{"title":"評価","description":"ご要望に応じて会場レビュー、予算スコーピング、プランレビューを実施します。"},{"title":"書面での提言","description":"自社サービスの売り込みではなく、明確で実行可能な提言をお渡しします。"},{"title":"任意のフォローアップ","description":"ご希望があれば、そのコンサルティング内容を提案のベースとして制作を実行します。"}]'::jsonb,
  ideal_for_ja = ARRAY['初めてハイブリッドイベントを企画するチーム', '専任のAV担当者がいない社内チーム', 'RFP・ベンダー選定プロセス', '既存の技術プランのセカンドオピニオン']::text[],
  seo_title_ja = '日本国内のイベント技術コンサルティングサービス | TOTAL MEDIA',
  seo_description_ja = '日本全国で独立系イベント技術コンサルティングを提供。社内にAV専門知識のないチーム向けに、会場評価、予算スコーピング、セカンドオピニオンレビューを行います。'
where slug = 'event-consultation';

